(function(){"use strict";const button=document.getElementById("mobileMenuToggle"),header=document.querySelector(".topbar"),home=document.getElementById("homeView");if(!button||!header||!home)return;function placeMenu(){const intro=document.body.classList.contains("home-active")&&!home.classList.contains("hidden")?home.querySelector(".home-intro"):null,heading=intro&&intro.querySelector("h1");heading?(button.parentElement!==intro||button.previousElementSibling!==heading)&&heading.after(button):button.previousElementSibling!==header&&header.after(button)}new MutationObserver(placeMenu).observe(home,{childList:!0}),new MutationObserver(placeMenu).observe(document.body,{attributes:!0,attributeFilter:["class"]}),placeMenu()})();
